INSERT INTO pos.products(sku, vendor_name, purchase_date, cost_price, selling_price, saree_type, material, color, rack_location)
SELECT 'DEMO-' || v.sku || '-' || g, 'Demo vendor', CURRENT_DATE, ROUND(v.price * 0.6), COALESCE(v.discount_price, v.price),
       p.fabric, p.fabric, v.color, 'DEMO'
  FROM demo_stock s
  JOIN store.product_variants v ON v.sku = s.sku
  JOIN store.products p ON p.id = v.product_id
  CROSS JOIN LATERAL generate_series(1, s.n) AS g
ON CONFLICT (sku) DO NOTHING;

INSERT INTO store.variant_inventory_items(inventory_product_id, variant_id)
SELECT pp.id, v.id
  FROM demo_stock s
  JOIN store.product_variants v ON v.sku = s.sku
  CROSS JOIN LATERAL generate_series(1, s.n) AS g
  JOIN pos.products pp ON pp.sku = 'DEMO-' || v.sku || '-' || g
ON CONFLICT DO NOTHING;

DROP TABLE demo_stock;
